using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using ProjectWait.M.Elevator;
using Object=UnityEngine.Object;
public static class VerifyHoverHV
{
 const string D="Assets/M/CodexTemp/ElevatorHoverReview_20261030~/";
 static ElevatorLesson l;static ElevatorDesktopControls c;static ElevatorPlayerMovement movement;static List<object> checks;static string mode;
 static Vector2 Centre=>new Vector2(Screen.width*.5f,Screen.height*.5f);
 static ElevatorObservation Obs(ElevatorClue clue)=>l.CollectObservations().First(o=>o.clue==clue&&o.gameObject.activeInHierarchy);
 static void Check(bool ok,string name){checks.Add(new{name,passed=ok});if(!ok)throw new Exception(name);}
 static async Task Wait(Func<bool> predicate,string description,int ms=10000){for(int i=0;i<ms&&!predicate();i+=50)await Task.Delay(50);Check(predicate(),description);}
 static async Task Mouse(Vector2 p,bool down=false){var state=new MouseState{position=p};if(down)state=state.WithButton(MouseButton.Left,true);InputSystem.QueueStateEvent(UnityEngine.InputSystem.Mouse.current,state);await Task.Delay(90);}
 static async Task Aim(ElevatorObservation o){var b=o.GetComponent<Collider>().bounds;var point=b.center;if(o.clue==ElevatorClue.Friend||o.clue==ElevatorClue.Rescuer)point+=Vector3.up*b.extents.y*.55f;var r=Quaternion.LookRotation(point-l.playerCamera.transform.position).eulerAngles;c.SetLookAngles(r.y,Mathf.DeltaAngle(0,r.x));await Mouse(Centre);await Task.Delay(120);}
 static async Task Click(ElevatorClue clue){var o=Obs(clue);await Wait(()=>l.CanInteract(clue),"Inspection available: "+clue);await Aim(o);Check(c.HoverTargetName==o.name,"Centre ray reaches "+clue+" (actual "+c.HoverTargetName+")");await Mouse(Centre,true);await Mouse(Centre);}
 static async Task Next(){await Wait(()=>l.view.ChoiceButtons.Count==1&&!l.CinematicBlocking,"Exactly one dialogue Next button is available");var b=l.view.ChoiceButtons[0];Check(b.name=="DialogueNext"&&b.GetComponentInChildren<TMPro.TMP_Text>().text=="다음","Conversation advances with a dedicated Next button");var r=Quaternion.LookRotation(b.transform.position-l.playerCamera.transform.position).eulerAngles;c.SetLookAngles(r.y,Mathf.DeltaAngle(0,r.x));await Mouse(Centre);Check(c.HoverTargetName==b.name,"Centre pointer selects Next");Check(((RectTransform)b.transform).rect.width<250,"Next uses a compact world-space button");await Mouse(Centre,true);await Mouse(Centre);}
 static async Task Shot(string name){await Task.Delay(150);await Awaitable.EndOfFrameAsync();ScreenCapture.CaptureScreenshot(D+mode+"_"+name+".png");await Task.Delay(160);}
 static void Warp(Vector3 feet,float yaw){movement.Controller.enabled=false;movement.transform.position=feet;movement.Controller.enabled=true;movement.CalibrateFeet(feet.y);movement.ResetVerticalMotion();c.SetLookAngles(yaw,0);Physics.SyncTransforms();}
 static void Walk(int frames=90){for(int i=0;i<frames;i++)movement.Move(Vector2.up,.02f,false);Physics.SyncTransforms();}
 static async Task Idle(){c.SetLookAngles(180,65);await Mouse(Centre);await Task.Delay(180);}
 public static async Task<string> Main()
 {
  for(int i=0;i<100;i++){l=Object.FindFirstObjectByType<ElevatorLesson>();if(Application.isPlaying&&l&&l.Flow!=null)break;await Task.Delay(100);}
  c=Object.FindFirstObjectByType<ElevatorDesktopControls>();movement=c.GetComponent<ElevatorPlayerMovement>();if(!movement)movement=Object.FindFirstObjectByType<ElevatorPlayerMovement>();mode=l.scenario.objectGuidedScene?"Guided":"Original";checks=new List<object>();string error=null;int initial=Time.frameCount;
  var oldSettings=InputSystem.settings;var temp=Object.Instantiate(oldSettings);temp.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temp.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temp;
  var hardware=UnityEngine.InputSystem.Mouse.current;bool enabled=hardware!=null&&hardware.enabled;if(enabled)InputSystem.DisableDevice(hardware);var mouse=InputSystem.AddDevice<UnityEngine.InputSystem.Mouse>("HoverRefinementQAMouse");mouse.MakeCurrent();
  try
  {
   l.simulateNoResponse=false;l.Restart();l.presentation.space.overlay.Advance(2);await Task.Delay(180);await Idle();
   Check(l.scenario.hints.All(h=>h.group.alpha==0),"No object hint appears without hover");Check(l.CollectObservations().All(o=>!o.shapeHighlight||!o.shapeHighlight.Visible),"No object glows automatically, including the correct object");Check(l.CollectObservations().Count(o=>o.gameObject.activeInHierarchy&&l.CanInteract(o.clue))>=5,"Multiple objects are inspectable at the same stage");Check(!l.CanInteract(ElevatorClue.LobbyCallUp),"Unavailable upward call stays disabled");
   var friend=Obs(ElevatorClue.Friend);await Aim(friend);Check(c.HoverTargetName==friend.name&&friend.shapeHighlight.Visible,"Hovering a non-goal friend highlights its silhouette");var hint=l.scenario.hints.First(h=>h.observation==friend);Check(hint.group.alpha>.98f,"The hovered object's explanation appears");Check(l.view.dialoguePanel.GetComponent<CanvasGroup>().alpha==0,"Object explanation temporarily hides the overlapping narrative card");await Shot("01_FriendHover");
   var world=hint.transform.position;var scale=hint.transform.lossyScale;movement.Move(new Vector2(-.4f,0),.15f,false);await Task.Delay(30);Check(Vector3.Distance(hint.transform.position,world)<.001f&&Vector3.Distance(hint.transform.lossyScale,scale)<.00001f,"Hint position and physical size remain fixed when the player moves");
   await Aim(Obs(ElevatorClue.LobbyCall));Check(!friend.shapeHighlight.Visible&&Obs(ElevatorClue.LobbyCall).shapeHighlight.Visible,"Switching hover removes the previous outline");Check(l.scenario.hints.Count(h=>h.group.alpha>.01f)==1,"Only the currently hovered explanation remains visible");await Shot("02_CallHover");await Idle();Check(l.scenario.hints.All(h=>h.group.alpha==0),"Hints disappear promptly after hover ends");
   c.SetLookAngles(139,-43);l.pauseMenu.Pause();await Task.Delay(120);var card=(RectTransform)l.pauseMenu.canvas.transform.Find("PauseCard");var vp=l.playerCamera.WorldToViewportPoint(card.TransformPoint(card.rect.center));Check(Mathf.Abs(vp.x-.5f)<.005f&&Mathf.Abs(vp.y-.5f)<.005f,"Pause card is centred in the view, even after a steep camera turn");Check(l.pauseMenu.canvas.renderMode==RenderMode.WorldSpace,"Pause remains world space");Check(l.pauseMenu.Buttons.Count()==4&&!l.pauseMenu.titleButton.interactable,"Pause has four buttons with title intentionally disabled");await Shot("03_PauseCentred");
   var resume=RectTransformUtility.WorldToScreenPoint(l.playerCamera,l.pauseMenu.resumeButton.transform.position);await Mouse(resume);Check(c.HoverTargetName==l.pauseMenu.resumeButton.name,"Free mouse pointer reaches the centred resume button");await Mouse(resume,true);await Mouse(resume);Check(!l.IsPaused&&Time.timeScale==1,"Actual resume-button click restores play");
   foreach(float x in new[]{-4.5f,3.9f,-2.58f,1.38f})
   {
    Warp(new Vector3(x,7.92f,-4.35f),180);await Task.Delay(80);Walk();Check(movement.FeetPosition.z> -5.3f&&movement.FeetPosition.z< -4.7f,"Basketball-side fixed wall or sidelight blocks passage at x="+x+": "+movement.FeetPosition.ToString("F3"));
   }
   Warp(new Vector3(-4.5f,0,-4.35f),180);Walk();Check(movement.FeetPosition.z> -5.3f&&movement.FeetPosition.z< -4.7f,"1F entrance wall also blocks passage");
   Warp(new Vector3(-.6f,7.92f,-4.35f),180);await Task.Delay(350);Walk();Check(movement.FeetPosition.z< -5.7f&&movement.FeetPosition.z> -6.4f,"Player crosses the sliding-door threshold and stops at the rear wall: "+movement.FeetPosition.ToString("F3"));
   Warp(new Vector3(8.1f,7.92f,-2.45f),0);Walk();Check(movement.FeetPosition.z< -1.9f&&movement.FeetPosition.z> -2.5f,"3F descending stair entrance is blocked: "+movement.FeetPosition.ToString("F3"));
   Warp(new Vector3(5.18f,0,-3),0);Walk();Check(movement.FeetPosition.z< -2.2f&&movement.FeetPosition.z> -2.7f,"1F ascending stair entrance is blocked: "+movement.FeetPosition.ToString("F3"));
   Warp(new Vector3(-5.47f,7.92f,1.1f),0);Walk();Check(movement.FeetPosition.z<2&&movement.FeetPosition.z>1.2f,"3F planter blocks the player capsule: "+movement.FeetPosition.ToString("F3"));
   Warp(new Vector3(-4.3f,7.92f,-.65f),270);Walk();Check(movement.FeetPosition.x> -5.3f&&movement.FeetPosition.x< -4.6f,"3F bench blocks the player capsule: "+movement.FeetPosition.ToString("F3"));
   Warp(new Vector3(-5.47f,0,1.1f),0);Walk();Check(movement.FeetPosition.z<2&&movement.FeetPosition.z>1.2f,"1F planter also blocks the player capsule");
   l.Restart();l.presentation.space.overlay.Advance(2);await Task.Delay(200);await Click(ElevatorClue.LobbyCall);await Wait(()=>l.Flow.Step==ElevatorStep.Boarding&&!l.CinematicBlocking,"Boarding completes",8500);await Click(ElevatorClue.FloorButtons);Check(l.Flow.DestinationSelected,"Floor button selects 1F");await Click(ElevatorClue.Friend);Check(l.Flow.Step==ElevatorStep.Proposal,"Friend hands over the ball");
   if(l.scenario.objectGuidedScene)await Click(ElevatorClue.Notice);else{var button=l.view.ChoiceButtons[0];var r=Quaternion.LookRotation(button.transform.position-l.playerCamera.transform.position).eulerAngles;c.SetLookAngles(r.y,Mathf.DeltaAngle(0,r.x));await Mouse(Centre);Check(c.HoverTargetName==button.name,"Original scene still offers its choice button");await Mouse(Centre,true);await Mouse(Centre);}
   await Wait(()=>l.Flow.Step==ElevatorStep.Stopped&&l.Flow.CanObserve&&!l.CinematicBlocking,"The no-jump route reaches the fault",6500);Check(l.Flow.JumpCount==0,"Fault does not require a jump");
   var step=l.Flow.Step;await Click(ElevatorClue.Door);Check(l.Flow.Step==step,"Inspecting the door is not interpreted as forcing it open");await Click(ElevatorClue.Notice);await Shot("04_PosterDescription");Check(l.Flow.Step==ElevatorStep.Stopped,"Inspecting the poster does not advance the fault response");
   await Aim(Obs(ElevatorClue.Intercom));await Shot("05_SidePanelDescription");await Click(ElevatorClue.Intercom);await Wait(()=>l.Flow.Step==ElevatorStep.Call&&!l.CinematicBlocking,"Emergency button connects the operator",4500);int presses=Obs(ElevatorClue.Intercom).feedback.PressCount;await Click(ElevatorClue.Intercom);Check(!l.Flow.SituationReported&&Obs(ElevatorClue.Intercom).feedback.PressCount==presses,"Pressing emergency again neither advances dialogue nor retriggers the button");await Shot("06_OperatorNext");
   await Next();Check(l.Flow.SituationReported&&!l.Flow.IdentityFound&&l.view.ChoiceButtons.Count==0,"Next reports the situation, then pauses for physical identification");await Click(ElevatorClue.Display);Check(!l.Flow.IdentityFound,"Inspecting another candidate does not pretend the identity was found");await Click(ElevatorClue.Identity);Check(l.Flow.IdentityFound,"Physical identity-plate inspection still identifies the lift");await Next();Check(l.Flow.LocationReported,"Next reports the identified location");await Next();Check(l.Flow.Step==ElevatorStep.Waiting,"Next acknowledges the operator advice");
   await Shot("07_ReassureFriend");Check(!l.view.dialogueText.text.Contains("만져")&&!l.view.dialogueText.text.Contains("기대"),"Waiting dialogue asks for reassurance without suggesting touching or leaning on the door");await Click(ElevatorClue.Friend);Check(l.Flow.Step==ElevatorStep.WaitingFade&&l.Flow.Reassured,"Reassuring the friend begins the waiting fade");
   await Wait(()=>l.Flow.Step==ElevatorStep.Rescue&&l.Flow.ReadyToExit&&!l.CinematicBlocking,"Fade leads into a checked rescue",10000);
   if(l.scenario.objectGuidedScene)await Click(ElevatorClue.Rescuer);else l.Continue();await Wait(()=>l.Flow.Step==ElevatorStep.ReturnLobby&&!l.CinematicBlocking,"Guided exit reaches the lobby",7000);
   if(l.scenario.objectGuidedScene)await Click(ElevatorClue.Rescuer);else l.Continue();await Wait(()=>l.Flow.Step==ElevatorStep.GroundFloor&&!l.CinematicBlocking,"Staff transition reaches 1F despite manual stair blockers",6000);if(l.scenario.objectGuidedScene)await Click(ElevatorClue.GroundExit);else{var exit=l.view.ChoiceButtons[0];var look=Quaternion.LookRotation(exit.transform.position-l.playerCamera.transform.position).eulerAngles;c.SetLookAngles(look.y,Mathf.DeltaAngle(0,look.x));await Mouse(Centre);Check(c.HoverTargetName==exit.name,"Original exit choice receives the pointer");await Mouse(Centre,true);await Mouse(Centre);}await Wait(()=>l.Flow.Step==ElevatorStep.Complete&&!l.CinematicBlocking,"The revised scenario reaches completion",9000);Check(l.Flow.HelpRequested&&l.Flow.LocationReported&&l.Flow.Reassured,"Completion retains all coping outcomes");await Shot("08_Completed");
   l.simulateNoResponse=true;l.DeveloperJump(3);l.Advance(2);l.presentation.space.overlay.Advance(2);await Task.Delay(150);await Click(ElevatorClue.Intercom);l.Advance(3);l.presentation.space.overlay.Advance(2);await Task.Delay(150);Check(l.Flow.Step==ElevatorStep.Unanswered,"No-response branch remains available");await Click(ElevatorClue.Phone);Check(l.Flow.UsedPhone&&l.Flow.Step==ElevatorStep.Call,"Phone fallback enters simulated 119 conversation");await Next();Check(l.Flow.SituationReported,"119 conversation also uses Next");
   l.simulateNoResponse=false;l.Restart();l.presentation.space.overlay.Advance(2);Check(Time.frameCount>initial+100,"Verification exercised live player frames");
  }
  catch(Exception e){error=e.ToString();ScreenCapture.CaptureScreenshot(D+mode+"_Failure.png");}
  finally{if(l.IsPaused)l.pauseMenu.Resume();InputSystem.RemoveDevice(mouse);if(enabled)InputSystem.EnableDevice(hardware);hardware?.MakeCurrent();InputSystem.settings=oldSettings;Object.Destroy(temp);}
  var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=error==null,mode,passed=checks.Count(x=>(bool)x.GetType().GetProperty("passed").GetValue(x)),checks,error,frameStart=initial,frameEnd=Time.frameCount},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(D+mode+"Verification.json",report);return report;
 }
}
